insert into public.projects (title, img, "desc", link, stack, sort_order) values
  ('E-PPID Online', '/projects/project1.webp', 'Developed a fullstack web application to streamline public information requests and documentation workflows. Designed system architecture, implemented real-time request tracking, and deployed the application on a Linux VPS, reducing processing time and increasing transparency for government stakeholders', '#', array['Laravel', 'React.js', 'MySQL'], 1),
  ('Cooperation Application System', '/projects/project2.webp', 'Built a web application that digitizes the submission, review, and approval of partnership and cooperation requests. Implemented multi-step approval workflows and document management with Laravel and MySQL, replacing a paper-based process with trackable online submissions.', '#', array['Laravel', 'MySQL'], 2),
  ('Website IMAKOM', '/projects/project3.webp', 'Developed the official website and admin panel for IMAKOM, centralizing member administration, announcements, and content publishing. Built with Laravel and MySQL so non-technical admins can manage the site without developer support.', '#', array['Laravel', 'MySQL'], 3),
  ('E-Archive Online', '/projects/project4.webp', 'Built a digital archiving system to store, categorize, and search official documents. Implemented structured metadata, role-based access, and fast search with Laravel and MySQL, cutting the time needed to locate archived records.', '#', array['Laravel', 'MySQL'], 4),
  ('E-Admission Online', '/projects/project5.webp', 'Developed an online student admission system covering registration, document upload, selection, and announcement of results. Built with Laravel and Vue.js, allowing applicants to register remotely and staff to process applications from a single dashboard.', '#', array['Laravel', 'Vue.js'], 5),
  ('E-Commerce Nanshop', '/projects/project6.webp', 'Built an e-commerce storefront with product catalog, cart, and checkout flow using Next.js and MySQL, focusing on a fast, responsive shopping experience across devices.', 'https://ahmadfrnando.github.io/ecommerce/', array['Next.js', 'MySQL'], 6),
  ('Neighborgood', '/projects/project7.webp', 'Designed and built a responsive company profile landing page with React.js, presenting services and contact information with clean layout and smooth interactions.', 'https://ahmadfrnando.github.io/landing-page/', array['React.js'], 7),
  ('Puskesmas Online', '/projects/project8.webp', 'Developed an immunization data and reporting system for the Sumber Mulyorejo Binjai health sub-center. Built with Laravel and Vue.js and containerized with Docker, replacing manual record books with searchable patient data and automated reports.', '#', array['Laravel', 'Vue.js', 'Docker'], 8),
  ('Point of Sale (POS) & ERP System', '/projects/project9.webp', 'Developed a POS and ERP system to manage sales transactions, inventory, and reporting. Responsible for backend development using Laravel and MySQL, API integration with React.js, and deployment on VPS environments, improving operational efficiency and data accuracy for business users', '#', array['Next.js', 'Laravel', 'MySQL', 'MinIO', 'Xendit', 'Docker'], 9),
  ('Human Resources Management System (HRMS)', '/projects/project10.webp', 'Built a web-based HR management system covering attendance, payroll, and performance evaluation modules. Implemented RESTful APIs, integrated biometric attendance devices, and optimized database performance using PostgreSQL, reducing manual data errors and improving payroll accuracy.', '#', array['Laravel', 'Next.js', 'PostgreSQL', 'MinIO', 'Docker'], 10),
  ('SiPangan', '/projects/project11.webp', 'Designed and developed a public-facing web platform to provide real-time food price information. Implemented role-based access control, automated updates, and responsive dashboards, supporting open-data initiatives and reducing manual data management', '#', array['Laravel', 'MySQL', 'Docker'], 11),
  ('Snapora', '/projects/project12.webp', 'Built a photo booth application with real-time image processing and social media sharing capabilities. Implemented a user-friendly interface, integrated camera APIs, and optimized image rendering for various devices, enhancing user engagement at events.', '#', array['Next.js', 'Laravel', 'MySQL', 'Xendit', 'MinIO', 'Docker'], 12);
